import react from "@vitejs/plugin-react";

export default defineConfig({
  resolve: {
    tsconfigPaths: true,
  },
  plugins: [react()],
  test: {
    environment: "jsdom",
    // Scoped to test files so Vitest never picks up Playwright specs (e2e/) or build output.
